def record_current_versions(apps, schema_editor):
    """Every round with criteria gets a history row for the version it is on now."""
    Solicitation = apps.get_model("solicitations", "Solicitation")
    RubricVersion = apps.get_model("solicitations", "RubricVersion")
    for round_ in Solicitation.objects.exclude(rubric_version="").exclude(evaluation_criteria=[]):
        RubricVersion.objects.get_or_create(
            solicitation=round_,
            version=round_.rubric_version,
            defaults={"criteria": round_.evaluation_criteria, "basis": round_.criteria_basis},
        )


